            { "b", 281, 0.2545, 0.7894, {"Princess Theradras","Princesse Theradras","Prinzessin Theradras","Princesa Theradras","Princesa Theradras"}, nil },
            { "n", 280, 0.5078, 0.5213, {"Maraudos (4th Khan), quest target","Maraudos (4e Khan), cible de quête","Maraudos (4. Khan), Questziel","Maraudos (4.º Khan), objetivo de misión","Maraudos (4º Khan), alvo de missão"} },
            { "n", 280, 0.2133, 0.6419, {"Jump down here","Sautez en contrebas ici","Hier hinunterspringen","Salta hacia abajo aquí","Pule para baixo aqui"} },
            { "n", 281, 0.2789, 0.3706, {"Jump down. Portal D: with the Scepter of Celebras (quest Legends of Maraudon) you get here directly from outside","Sautez en contrebas. Portail D : avec le Sceptre de Celebras (quête Légendes de Maraudon), vous arrivez ici directement depuis l'extérieur","Hinunterspringen. Portal D: mit dem Szepter von Celebras (Quest „Legenden von Maraudon“) kommt man von draußen direkt hierher","Salta hacia abajo. Portal D: con el Cetro de Celebras (misión Leyendas de Maraudón) llegas aquí directamente desde fuera","Pule para baixo. Portal D: com o Cetro de Celebras (missão Lendas de Maraudon), você chega aqui direto de fora"} },
            { "n", 281, 0.3744, 0.7917, {"Bridge to the Princess's island. Rotgrip lives in the water below: jump off the bridge","Pont vers l'île de la Princesse. Grippe-charogne vit dans l'eau en contrebas : sautez du pont","Brücke zur Insel der Prinzessin. Faulschnapper lebt im Wasser darunter: von der Brücke springen","Puente a la isla de la Princesa. Escamapodrida vive en el agua de abajo: salta desde el puente","Ponte para a ilha da Princesa. Putrigarra vive na água lá embaixo: pule da ponte"} },
